export const INITIAL=()=>({version:1,chapter:0,maxChapter:0,landmarks:[],sensor:false,checks:[],route:'',audit:[],conclusion:false,gates:[70,10,10],yard:false,outcome:'',rebuild:[],events:[],peopleView:false});
export const CHECKS=['capacity','water','access'];
export const LANDMARKS=['clinic','library','school'];
export const RECORDS=['register','integration','test'];
export function ready(s,n=s.chapter){return [true,LANDMARKS.every(k=>s.landmarks.includes(k)),s.sensor,CHECKS.every(k=>s.checks.includes(k))&&s.route==='upper',RECORDS.every(k=>s.audit.includes(k))&&s.conclusion,!!s.outcome,s.rebuild.length===3][n]??false;}
export function flow(g){const [east,b1,b2]=g.map(Number);return {east,b1,b2,spill:100-east-b1-b2};}
export function evaluatePlan(s){const f=flow(s.gates);if(f.spill<0)return {valid:false,safe:false,message:'The allocations exceed the incoming flow. Bring the total back to 100%.'};if(f.b1>30||f.b2>30)return {valid:false,safe:false,message:'A retention basin is over its fictional 30% game capacity.'};if(f.spill>30)return {valid:true,safe:false,message:'The spillway exceeds its game capacity. The hospital access road is exposed.'};if(f.spill>0&&!s.yard)return {valid:false,safe:false,message:'Confirm the industrial yard is clear, including the caretaker’s family.'};if(f.east>25)return {valid:true,safe:false,message:'Too much water is still directed toward Aangan.'};if(!ready(s,3)||!ready(s,4))return {valid:false,safe:false,message:'Verify the shelter, route, and population layer first.'};return {valid:true,safe:true,message:'The revised plan protects access and shares the surge within the verified game limits.'};}
export function safeLoad(raw){try{const x=JSON.parse(raw);if(x.version!==1)return INITIAL();const s={...INITIAL(),...x};s.chapter=Math.max(0,Math.min(6,Number(s.chapter)||0));s.maxChapter=Math.max(s.chapter,Math.min(6,Number(s.maxChapter)||0));for(const k of ['landmarks','checks','audit','rebuild','events'])if(!Array.isArray(s[k]))s[k]=[];if(!Array.isArray(s.gates)||s.gates.length!==3||s.gates.some(v=>!Number.isFinite(v)||v<0||v>100))s.gates=[70,10,10];return s;}catch{return INITIAL();}}
export function demoState(chapter){return {...INITIAL(),chapter,maxChapter:6,landmarks:[...LANDMARKS],sensor:true,checks:[...CHECKS],route:'upper',audit:[...RECORDS],conclusion:true,peopleView:true,gates:[20,30,30],yard:true,...(chapter===1?{landmarks:[]}:{}),...(chapter===2?{sensor:false}:{}),...(chapter===3?{checks:[],route:''}:{}),...(chapter===4?{audit:[],conclusion:false}:{}),...(chapter===6?{outcome:'held'}:{})};}
